import Foundation

struct SM64FishObjectEffectRecord: Equatable, Sendable {
    let objectID: SM64ObjectID
    let role: SM64FishRole
    let groupOutput: SM64FishGroupOutput?
    let fishOutput: SM64FishOutput?
    let spawnedChildren: [SM64ObjectID]
}

final class SM64FishObjectBridge {
    static let fishBehaviorIdentity: UInt64 = 0x6268_765F_666973
    static let fishGroupBehaviorIdentity: UInt64 = 0x6268_765F_666770
    static let fish2BehaviorIdentity: UInt64 = 0x6268_765F_666732
    static let fish3BehaviorIdentity: UInt64 = 0x6268_765F_666733
    static let largeFishGroupBehaviorIdentity: UInt64 = 0x6268_765F_6C6667
