    @discardableResult func attachGroup(_ id:SM64ObjectID,variant:SM64FishVariant,position:SM64ObjectVector3,distanceToMario:Float,secretAquarium:Bool,in pool:SM64ObjectPool)->Bool{guard pool.record(for:id) != nil else{return false};states[id]=State(role:.group,variant:variant,secretAquarium:secretAquarium,parent:nil,parentDuplicate:false,distanceToMario:distanceToMario,angleToMario:0,angleToHome:0);return pool.mutate(id){r in r.position=position;r.homePosition=position;r.distanceToMario=distanceToMario;r.objectFlags |= SM64ObjectScheduler.objectFlagUpdateGfxPositionAndAngle|SM64ObjectScheduler.objectFlagBuildTransform}}
    @discardableResult func spawnFish(in engineState:SM64SwiftEngineState,parent:SM64ObjectID?=nil,position:SM64ObjectVector3 = .zero,variant:SM64FishVariant = .blue20)throws->SM64ObjectID{let id=try engineState.spawnObject(in:.default,model:Self.fishModel,behaviorIdentity:Self.fishBehaviorIdentity,parent:parent);guard attachFish(id,variant:variant,parent:parent,position:position,in:engineState.objects)else{_ = engineState.objects.despawn(id);preconditionFailure("newly spawned fish could not attach")};return id}
    @discardableResult func attachFish(_ id:SM64ObjectID,variant:SM64FishVariant,parent:SM64ObjectID?,position:SM64ObjectVector3,in pool:SM64ObjectPool)->Bool{guard pool.record(for:id) != nil else{return false};states[id]=State(role:.fish,variant:variant,secretAquarium:false,parent:parent,parentDuplicate:false,distanceToMario:10_000,angleToMario:0,angleToHome:0);return pool.mutate(id){r in r.position=position;r.homePosition=position;r.forwardVelocity=3;r.objectFlags |= SM64ObjectScheduler.objectFlagUpdateGfxPositionAndAngle|SM64ObjectScheduler.objectFlagBuildTransform}}
    @discardableResult func setGroupInput(distanceToMario:Float,secretAquarium:Bool=false,for id:SM64ObjectID)->Bool{guard var s=states[id],s.role == .group else{return false};s.distanceToMario=distanceToMario;s.secretAquarium=secretAquarium;states[id]=s;return true}
