    @discardableResult func updateInline(_ id:SM64ObjectID,state engineState:SM64SwiftEngineState)->Bool{guard var s=states[id],let record=engineState.objects.record(for:id)else{return false};if s.role == .group{let o=SM64FishBehavior.updateGroup(action:record.action,variant:s.variant,distanceToMario:s.distanceToMario,secretAquarium:s.secretAquarium);var children:[SM64ObjectID]=[];if o.spawnedChildren>0{for _ in 0..<o.spawnedChildren{if let child=try? spawnFish(in:engineState,parent:id,position:record.position,variant:o.variant){children.append(child)}}};_ = engineState.objects.mutate(id){$0.action=o.action};effectLog.append(.init(objectID:id,role:.group,groupOutput:o,fishOutput:nil,spawnedChildren:children));s.distanceToMario=10_000;states[id]=s;return true};let parentDuplicate=s.parentDuplicate || s.parent.flatMap{engineState.objects.record(for:$0)?.action == 2} == true;let o=SM64FishBehavior.updateFish(action:record.action,timer:record.timer,position:record.position,moveYaw:record.moveAngles.yaw,forwardVelocity:record.forwardVelocity,targetY:record.position.y+100,angleToMario:s.angleToMario,angleToHome:s.angleToHome,parentDuplicate:parentDuplicate);s.parentDuplicate=false;s.distanceToMario=10_000;states[id]=s;_ = engineState.objects.mutate(id){n in n.action=o.action;n.timer=o.timer;n.position=o.position;n.moveAngles.yaw=o.moveYaw;n.forwardVelocity=o.forwardVelocity;n.animationState=Int32(o.animationAcceleration*100);if o.shouldDelete{n.activeFlags=0};n.objectFlags |= SM64ObjectScheduler.objectFlagUpdateGfxPositionAndAngle|SM64ObjectScheduler.objectFlagBuildTransform};effectLog.append(.init(objectID:id,role:.fish,groupOutput:nil,fishOutput:o,spawnedChildren:[]));return true}
    func remove(_ id:SM64ObjectID){states.removeValue(forKey:id)};func pruneExternal(unloaded:[SM64ObjectID],pool:SM64ObjectPool){for id in unloaded{remove(id)};for id in registeredIDs where pool.record(for:id)==nil{remove(id)}}
}
